import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem80 preserva operação e identidade sem converter tamanho M em cabine',()=>{const p={id:'H17ykC6IlHMpWBEMnEQ7',titulo:'Mala De Viagem 10kg Promoção Rodas 360° Miami Com Frasqueira',preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.equal(x.preco,p.preco);assert.equal(x.linkAfiliado,p.linkAfiliado);assert.deepEqual(correctProductData(x),x);assert.equal(correctProductData({...p,titulo:'Outra mala',comentario:'manter'}).comentario,'manter');assert.match(x.comentario,/tamanho M/);assert.match(x.comentario,/Não presumimos que seja uma mala de cabine/);assert.doesNotMatch(x.pros,/TSA|cabine|2.*5.*cm|10 kg/i);});
